    col_cuts = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    def regions(length, cuts):
        bounds = [-1] + cuts + [length]
        return [(bounds[i] + 1, bounds[i + 1])
                for i in range(len(bounds) - 1)
                if bounds[i + 1] > bounds[i] + 1]

    row_regions = regions(h, row_cuts)
    col_regions = regions(w, col_cuts)

